    """
    Generates a new string by moving each character five steps ahead in the alphabet.
    """
    encoded = []
    for char in s:
        if char.isalpha():
            shifted = ord(char) + 5
            if char.islower():
                if shifted > ord('z'):
                    shifted -= 26
            elif char.isupper():
                if shifted > ord('Z'):
                    shifted -= 26
            encoded.append(chr(shifted))
        else:
            encoded.append(char)
    return ''.join(encoded)

def decode_shift(s: str) -> str:
    """
    Retrieves the original string from one that was encoded by the encode_shift function.
    """
    decoded = []
    for char in s:
        if char.isalpha():
            shifted = ord(char) - 5
            if char.islower():
                if shifted < ord('a'):
                    shifted += 26
            elif char.isupper():
                if shifted < ord('A'):
                    shifted += 26
            decoded.append(chr(shifted))
        else:
            decoded.append(char)
    return ''.join(decoded)",
